      comprendre: {},
      completer: { kind: 'complete', ask: 'Affiche « Sans mention » si la note est de 10 (compris) à 12 (non compris), « Autre » sinon.', template: 'if ($note [[]] 10 [[]] $note [[]] 12) {\n    echo "Sans mention";\n} else {\n    echo "Autre";\n}', fill: ['>=', '&&', '<'], words: ['>=', '>', '<', '<=', '&&', '||'], ref: 'if ($note >= 10 && $note < 12) {\n    echo "Sans mention";\n} else {\n    echo "Autre";\n}', vars: { note: 11 }, hidden: [{ vars: { note: 10 }, label: '$note = 10 (pile sur la borne)' }, { vars: { note: 12 }, label: '$note = 12 (pile sur la borne)' }, { vars: { note: 9.5 } }, { vars: { note: 15 } }], hints: ['Un intervalle, ce sont deux conditions vraies à la fois.', 'if ($note >= 10 && $note < 12) {'] },
      reparer: { kind: 'repair', ask: 'La vitrine doit rester entre 18 et 22 degrés, bornes comprises : affiche « OK » dans ce cas, « Alerte » sinon. Ce programme affiche « OK » même à 30 degrés : répare-le.', starter: 'if ($temp >= 18 || $temp <= 22) {\n    echo "OK";\n} else {\n    echo "Alerte";\n}', ref: 'if ($temp >= 18 && $temp <= 22) {\n    echo "OK";\n} else {\n    echo "Alerte";\n}', vars: { temp: 30 }, hidden: [{ vars: { temp: 18 }, label: '$temp = 18 (pile sur la borne)' }, { vars: { temp: 22 }, label: '$temp = 22 (pile sur la borne)' }, { vars: { temp: 17 } }, { vars: { temp: 23 } }, { vars: { temp: 20 } }], traps: ['if ($temp > 18 && $temp < 22) {\n    echo "OK";\n} else {\n    echo "Alerte";\n}'], ir: [{ re: /\|\|/, text: 'Avec <code>||</code>, une seule condition vraie suffit, et toute température est au-dessus de 18 ou en dessous de 22. Pour « entre », c\'est <code>&amp;&amp;</code>.' }, { re: />\s*18|<\s*22/, text: '« Bornes comprises » : 18 et 22 sont OK, c\'est <code>&gt;=</code> et <code>&lt;=</code>.' }], hints: ['« Entre » veut dire « les deux à la fois ».', 'if ($temp >= 18 && $temp <= 22) {'] },
      ecrire1: { kind: 'write', ask: 'Affiche « Gratuit » pour les moins de 26 ans et pour les 65 ans et plus, « 9 € » pour les autres.', ref: 'if ($age < 26 || $age >= 65) {\n    echo "Gratuit";\n} else {\n    echo "9 €";\n}', vars: { age: 70 }, hidden: [{ vars: { age: 26 }, label: '$age = 26 (pile sur la borne)' }, { vars: { age: 65 }, label: '$age = 65 (pile sur la borne)' }, { vars: { age: 25 } }, { vars: { age: 64 } }, { vars: { age: 40 } }], traps: ['if ($age < 26 || $age > 65) {\n    echo "Gratuit";\n} else {\n    echo "9 €";\n}', 'if ($age <= 26 || $age >= 65) {\n    echo "Gratuit";\n} else {\n    echo "9 €";\n}'], ir: [{ re: /&&/, text: 'Personne n\'a à la fois moins de 26 ans et plus de 65 : « les uns et les autres », en PHP, c\'est <code>||</code>.' }], hints: ['Deux groupes de visiteurs gratuits : l\'un OU l\'autre suffit.', 'if ($age < 26 || $age … 65) {\n    …\n} else {\n    …\n}'] },
